def is_undulating(n):
    n = str(n)
    if len(n) <= 2:
        return True
    first = n[0]
    second = n[1]
    for i in range(2, len(n)):
        if i % 2 == 0:
            if n[i] != first:
                return False
        else:
            if n[i] != second:
                return False
    return True

